CREATE TABLE preventive_plans(id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plants(id), asset_id TEXT NOT NULL REFERENCES assets(id), owner_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL, enabled INTEGER NOT NULL CHECK(enabled IN(0,1)), template TEXT NOT NULL, next_index INTEGER NOT NULL, next_due TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_error TEXT);
CREATE INDEX preventive_due ON preventive_plans(enabled,next_due);
CREATE TABLE preventive_versions(plan_id TEXT NOT NULL REFERENCES preventive_plans(id), version INTEGER NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, reason TEXT NOT NULL, template TEXT NOT NULL, enabled INTEGER NOT NULL, PRIMARY KEY(plan_id,version));
CREATE TABLE preventive_occurrences(id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES preventive_plans(id), version INTEGER NOT NULL, due_at TEXT NOT NULL, overdue_at TEXT NOT NULL, work_order_id TEXT NOT NULL UNIQUE REFERENCES work_orders(id), created_at TEXT NOT NULL, UNIQUE(plan_id,due_at));
